//! The HANDOVER of a callback (`.waitForTaskToken`) task's token: the window in which
//! that token answers its task while the integration call carrying it is still in
//! flight.
//!
//! "Task tokens are generated by Step Functions when tasks are assigned to a worker, or
//! in the context object when a workflow enters a task state" — so a callback task's
//! token exists as the state is entered, travels out WITH the call its `Parameters` put
//! it in, and answers the task from that instant. The work it reaches may report the
//! task's outcome straight away, from inside the very call that delivered it: a Lambda
//! function handed `$$.Task.Token` calling `SendTaskSuccess` through the SDK its runtime
//! supplies is the documented shape of the pattern, and that call arrives while the
//! invocation — and the walk waiting for it — is still going.
//!
//! The suspended task cannot serve it: the walk records the suspension only once its call
//! has answered, and the request that owns the walk writes it only once the walk is over.
//! What serves it is this module's handover record ([`super::CallbackHandover`]), written
//! before the call and read back after it:
//!
//! * the walk hands the token over ([`super::integration::Tasks::hand_over`]) BEFORE the
//!   call, so a `SendTask*` quoting it is accepted from then on;
//! * `SendTaskSuccess`/`SendTaskFailure` record what they answered against the handover
//!   and report the task answered, interpreting nothing: the execution they would
//!   continue has not been written yet, and continuing it twice is exactly what must not
//!   happen;
//! * the walk reads the answer back when the call returns
//!   ([`super::integration::Tasks::settle_handover`]), which both ENDS the handover and
//!   decides the state: an answer is the task's own outcome, and no answer suspends at
//!   the token exactly as before, with the stored task answering it from then on.
//!
//! So the execution is continued ONCE, by the request that owns the walk, whichever side
//! of the call's answer the `SendTask*` arrived on.
//!
//! This is the seam's one implementation over this service's own store, reached through
//! the engine the operation holds — the shape [`super::task_authorization::role_gate`]
//! and [`super::http_task::connections`] reach other stores through.

use ::std::sync::Arc;

use super::integration::{CallbackHandovers, Handovers, Replied};

/// This walk's handovers, recorded in this service's own store; `None` for an engine
/// carrying no store of this service, where there is nothing to record one in.
pub fn handovers<Eng: Send + Sync + 'static>(engine: &Arc<Eng>) -> Option<Handovers> {
    super::service_state(&**engine)?;
    Some(Arc::new(StoredHandovers {
        engine: Arc::clone(engine),
    }))
}

/// The handovers of one walk, held in the store this service's operations read and write.
struct StoredHandovers<Eng> {
    engine: Arc<Eng>,
}

impl<Eng: Send + Sync + 'static> CallbackHandovers for StoredHandovers<Eng> {
    fn handed_over(&self, token: &str, execution_arn: &str, state_name: &str) {
        let Some(state) = super::service_state(&*self.engine) else {
            return;
        };
        state
            .lock()
            .hand_over_callback(token, execution_arn, state_name, super::now());
    }

    fn settled(&self, token: &str) -> Option<Replied> {
        let state = super::service_state(&*self.engine)?;
        let settled = state.lock().settle_callback_handover(token);
        settled
    }
}

/// Debug without disclosing what the store holds.
impl<Eng> ::std::fmt::Debug for StoredHandovers<Eng> {
    fn fmt(&self, formatter: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
        formatter.debug_struct("StoredHandovers").finish()
    }
}
